changeSet.sql:
ALTER TABLE score_fragment
  ADD CONSTRAINT ck_score_fragment_category CHECK (category IN ('INTRODUCTION', 'MARCH', 'SIGNAL', 'ROLL', 'OTHER')),
  ADD CONSTRAINT ck_score_fragment_kind CHECK (kind IN ('PITCHED', 'PERCUSSION')),
  ADD CONSTRAINT ck_score_fragment_measures CHECK (measure_count BETWEEN 1 AND 64),
  ADD CONSTRAINT ck_score_fragment_percussion CHECK ((kind = 'PERCUSSION') = (percussion_keys_json IS NOT NULL));
CREATE UNIQUE INDEX uq_score_fragment_name ON score_fragment (lower(name)) WHERE deleted = FALSE;
